dashboard.definition:
{
  "title": "HANA Trace",
  "description": "SAP HANA trace log analysis — error and fatal events, top components, and source file hotspots",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Linux",
            "value": "logserv_linux"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Trace Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Ahana%3Atracelogs%22%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_kpi_errors": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_errors"
      },
      "title": "Errors / Fatal",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Ahana%3Atracelogs%22%20hana_trace_severity%20IN%20%28%22error%22%2C%20%22fatal%22%29%20%7C%20sort%20-_time&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_kpi_components": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_components"
      },
      "title": "Unique Components",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22sap%3Ahana%3Atracelogs%22%20hana_trace_component%3D%2A%20%7C%20where%20len%28hana_trace_component%29%20%3E%203%20AND%20hana_trace_component%21%3D%22INFO%22%20AND%20hana_trace_component%21%3D%22of%22%20AND%20hana_trace_component%21%3D%22service%3A%22%20%7C%20stats%20count%20as%20Events%2C%20dc%28hana_trace_source_file%29%20as%20%22Source%20Files%22%2C%20values%28hana_trace_severity%29%20as%20Severities%20by%20hana_trace_component%20%7C%20sort%20-Events%20%7C%20rename%20hana_trace_component%20as%20Component&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_trace_volume": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_trace_volume"
      },
      "title": "Trace Volume Over Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_by_severity": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_by_severity"
      },
      "title": "Trace Events by Severity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "info": "#0877a6",
          "warning": "#f1813f",
          "error": "#dc4e41",
          "fatal": "#dc4e41"
        },
        "dataValuesDisplay": "off"
      }
    },
    "viz_top_components": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_top_components"
      },
      "title": "Top Components",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_component_severity": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_component_severity"
      },
      "title": "Component by Severity (Top 10)",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "info": "#0877a6",
          "warning": "#f1813f",
          "error": "#dc4e41",
          "fatal": "#dc4e41"
        },
        "dataValuesDisplay": "off"
      }
    },
    "viz_source_hotspots": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_source_hotspots"
      },
      "title": "Source File Hotspots",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_sid_instance": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_sid_instance"
      },
      "title": "Activity by SID / Instance",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_error_detail": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_error_detail"
      },
      "title": "Recent Errors / Fatal Events",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_rect_r1l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r1r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_more_info": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_more_info"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "https://splunk.github.io/splunk-sap-logserv/content/logserv-app/dashboards/applications/#hana-trace",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_errors": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_severity IN (\"error\", \"fatal\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_components": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" | eventstats dc(hana_trace_component) as window_dc | timechart span=1d dc(hana_trace_component) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_trace_volume": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" | timechart span=1d count as \"Trace Events\""
      }
    },
    "ds_by_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_severity=* | timechart span=1d count by hana_trace_severity"
      }
    },
    "ds_top_components": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_component=*  | where len(hana_trace_component) > 3 AND hana_trace_component!=\"INFO\" AND hana_trace_component!=\"of\" AND hana_trace_component!=\"service:\" | stats count as Events dc(hana_trace_source_file) as \"Source Files\" values(hana_trace_severity) as Severities by hana_trace_component | sort -Events | head 20 | rename hana_trace_component as Component"
      }
    },
    "ds_component_severity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_component=* hana_trace_severity=*  | where len(hana_trace_component) > 3 AND hana_trace_component!=\"INFO\" AND hana_trace_component!=\"of\" AND hana_trace_component!=\"service:\" | stats count by hana_trace_component hana_trace_severity | sort -count | head 50 | chart sum(count) over hana_trace_component by hana_trace_severity | sort -info | head 10 | rename hana_trace_component as Component"
      }
    },
    "ds_source_hotspots": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_source_file=*  | where len(hana_trace_component) > 3 AND hana_trace_component!=\"INFO\" AND hana_trace_component!=\"of\" AND hana_trace_component!=\"service:\" | stats count as Events dc(hana_trace_source_line) as \"Unique Lines\" latest(hana_trace_severity) as \"Latest Severity\" by hana_trace_source_file hana_trace_component | sort -Events | head 20 | rename hana_trace_source_file as \"Source File\" hana_trace_component as Component"
      }
    },
    "ds_sid_instance": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" | stats count by sap_sid hana_instance | sort -count | head 20 | rename sap_sid as SID hana_instance as Instance"
      }
    },
    "ds_error_detail": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:tracelogs\" hana_trace_severity IN (\"error\", \"fatal\") | table _time sap_sid hana_instance hana_trace_component hana_trace_source_file hana_trace_source_line hana_trace_severity | sort -_time | head 30 | rename sap_sid as SID hana_instance as Instance hana_trace_component as Component hana_trace_source_file as \"Source File\" hana_trace_source_line as Line hana_trace_severity as Severity"
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_more_info": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"More Info\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1251,
          "width": 1920,
          "backgroundColor": "#0d1117"
        },
        "structure": [
          {
            "item": "viz_nav_go",
            "type": "block",
            "position": {
              "x": 10,
              "y": 10,
              "w": 120,
              "h": 25
            }
          },
          {
            "item": "viz_kpi_rect_1",
            "type": "block",
            "position": {
              "x": 10,
              "y": 45,
              "w": 620,
              "h": 140
            }
          },
          {
            "item": "viz_kpi_total",
            "type": "block",
            "position": {
              "x": 15,
              "y": 50,
              "w": 610,
              "h": 130
            }
          },
          {
            "item": "viz_kpi_rect_2",
            "type": "block",
